import 'package:json_annotation/json_annotation.dart';part 'division_list_response.g.dart';@JsonSerializable()class DivisionListResponse {  final bool success;  final String message;  final DivisionListData? data;  DivisionListResponse({    required this.success,    required this.message,    this.data,  });  factory DivisionListResponse.fromJson(Map<String, dynamic> json) =>      _$DivisionListResponseFromJson(json);  Map<String, dynamic> toJson() => _$DivisionListResponseToJson(this);}@JsonSerializable()class DivisionListData {  final List<DivisionItem>? items;  final Pagination? pagination;  DivisionListData({    required this.items,    required this.pagination,  });  factory DivisionListData.fromJson(Map<String, dynamic> json) =>      _$DivisionListDataFromJson(json);  Map<String, dynamic> toJson() => _$DivisionListDataToJson(this);}@JsonSerializable()class DivisionItem {  @JsonKey(name: 'division_id')  final int? divisionId;  final String? name;  @JsonKey(name: 'zone_id')  final int? zoneId;  @JsonKey(name: 'is_active')  final int? isActive;  @JsonKey(name: 'created_date')  final String? createdDate;  @JsonKey(name: 'updated_date')  final String? updatedDate;  DivisionItem({    this.divisionId,    this.name,    this.zoneId,    this.isActive,    this.createdDate,    this.updatedDate,  });  factory DivisionItem.fromJson(Map<String, dynamic> json) =>      _$DivisionItemFromJson(json);  Map<String, dynamic> toJson() => _$DivisionItemToJson(this);}@JsonSerializable()class Pagination {  final int total;  final int page;  final int limit;  @JsonKey(name: 'totalPages')  final int totalPages;  Pagination({    required this.total,    required this.page,    required this.limit,    required this.totalPages,  });  factory Pagination.fromJson(Map<String, dynamic> json) =>      _$PaginationFromJson(json);  Map<String, dynamic> toJson() => _$PaginationToJson(this);}